@php
    $extractAllPhotosHelper = function ($item) {
        $found = [];
        if (empty($item)) {
            return $found;
        }
        if (is_object($item)) {
            $item = (array) $item;
        }
        if (!is_array($item)) {
            return $found;
        }

        $keys = [
            'photos',
            'exhibit_photos',
            'evidence_photos',
            'photo',
            'exhibit_photo',
            'photo_url',
            'image',
            'image_path',
            'image_url',
            'file_path',
            'attachment',
            'attachments',
        ];
        foreach ($keys as $k) {
            if (!empty($item[$k])) {
                $val = $item[$k];
                if (is_string($val)) {
                    $val = trim($val);
                    if (str_starts_with($val, '[') || str_starts_with($val, '{')) {
                        $dec = json_decode($val, true);
                        if (is_array($dec)) {
                            foreach ($dec as $p) {
                                if (!empty($p) && is_string($p)) {
                                    $found[] = $p;
                                }
                            }
                        } else {
                            $found[] = $val;
                        }
                    } else {
                        $found[] = $val;
                    }
                } elseif (is_array($val)) {
                    foreach ($val as $p) {
                        if (!empty($p) && is_string($p)) {
                            $found[] = $p;
                        }
                    }
                }
            }
        }
        return array_values(array_unique($found));
    };

    $formatPhotoUrlHelper = function ($p) {
        if (empty($p)) {
            return '';
        }
        $p = trim((string) $p);
        if (str_starts_with($p, 'http://') || str_starts_with($p, 'https://') || str_starts_with($p, 'data:')) {
            return $p;
        }
        $clean = ltrim($p, '/');
        if (str_starts_with($clean, 'storage/')) {
            return asset($clean);
        }
        if (file_exists(public_path($clean))) {
            return asset($clean);
        }
        return asset('storage/' . $clean);
    };
    $authUser = auth()->user();
    $isMultiCase = ($case instanceof \App\Models\ForensicCase)
        ? $case->isMultipleSuspect()
        : (($case->underlyingRecord ?? null) instanceof \App\Models\MultipleSuspectCase || ($case instanceof \App\Models\MultipleSuspectCase) || !empty($case->total_suspects_count) || !empty($case->is_multiple));
    $activeSuspectHasSavedResult = false;
    $activeSuspectHasDrugExhibit = false;
    $isHof =
        ($authUser &&
            $authUser->is_head &&
            ($authUser->unit === 'Forensic Directorate' ||
                $authUser->unit === 'Forensic Head' ||
                $authUser->unit === 'Directorate Head' ||
                str_contains($authUser->unit ?? '', 'Forensic'))) ||
        request()->is('Forensic_Head*') ||
        session('user_role') === 'HOF';
    $dbLabHead = \App\Models\User::where('unit', 'LIKE', '%Lab%')->where('is_head', true)->first();
    $defaultLabHeadName = $dbLabHead ? $dbLabHead->fullname : 'N/A';
    $officerName = auth()->user()->fullname ?? (session('user_name') ?? ($authUser->fullname ?? ($defaultLabHeadName !== 'N/A' ? $defaultLabHeadName : 'N/A')));
    $officerRole = $isHof ? 'Forensic Head' : 'Commanding Officer';

    $reqFrom = request()->query('from') ?? (request()->query('unit') ?? request()->query('source'));
    $userUnit = $authUser->unit ?? (session('user_unit') ?? '');
    $referer = request()->header('referer') ?? '';

    if (!empty($reqFrom)) {
        if (str_contains(strtolower($reqFrom), 'crime') || str_contains(strtolower($reqFrom), 'field')) {
            $activeUnitContext = 'Crime Scene Support';
        } elseif (str_contains(strtolower($reqFrom), 'lab')) {
            $activeUnitContext = 'Lab Analysis';
        } elseif (str_contains(strtolower($reqFrom), 'evidence')) {
            $activeUnitContext = 'Evidence Management';
        } elseif (str_contains(strtolower($reqFrom), 'digital') || str_contains(strtolower($reqFrom), 'physical')) {
            $activeUnitContext = 'Digital & Physical Forensics';
        } else {
            $activeUnitContext = $reqFrom;
        }
    } elseif (request()->is('Lab_Analysis*') || request()->is('lab-analysis*') || request()->is('lab-result*')) {
        $activeUnitContext = 'Lab Analysis';
    } elseif (request()->is('Crime_Scene_Support*') || request()->is('crime-scene-support*')) {
        $activeUnitContext = 'Crime Scene Support';
    } elseif (request()->is('Digital_Forensics*') || request()->is('digital-forensics*')) {
        $activeUnitContext = 'Digital & Physical Forensics';
    } elseif (request()->is('Evidence_Management*') || request()->is('evidence-management*')) {
        $activeUnitContext = 'Evidence Management';
    } elseif (!empty($userUnit)) {
        if (str_contains(strtolower($userUnit), 'digital') || str_contains(strtolower($userUnit), 'physical')) {
            $activeUnitContext = 'Digital & Physical Forensics';
        } elseif (str_contains(strtolower($userUnit), 'evidence')) {
            $activeUnitContext = 'Evidence Management';
        } elseif (str_contains(strtolower($userUnit), 'lab')) {
            $activeUnitContext = 'Lab Analysis';
        } elseif (str_contains(strtolower($userUnit), 'crime') || str_contains(strtolower($userUnit), 'field')) {
            $activeUnitContext = 'Crime Scene Support';
        } else {
            $activeUnitContext = $userUnit;
        }
    } else {
        if (
            str_contains(strtolower($case->unit_name ?? ''), 'digital') ||
            str_contains(strtolower($case->unit_name ?? ''), 'physical')
        ) {
            $activeUnitContext = 'Digital & Physical Forensics';
        } elseif (str_contains(strtolower($case->unit_name ?? ''), 'evidence')) {
            $activeUnitContext = 'Evidence Management';
        } elseif (str_contains(strtolower($case->unit_name ?? ''), 'lab')) {
            $activeUnitContext = 'Lab Analysis';
        } else {
            $activeUnitContext = $case->unit_name ?? 'Crime Scene Support';
        }
    }

    $reqFrom =
        request('from') ??
        (request('unit') ??
            (request('source') ??
                (request()->query('from') ?? (request()->query('unit') ?? request()->query('source')))));
    $isDigitalForensicsRegister =
        str_contains(strtolower($reqFrom ?? ''), 'digital_forensics_register') ||
        str_contains(strtolower($reqFrom ?? ''), 'digital_register') ||
        $reqFrom === 'Digital_Forensics_Register';
    $isDigitalForensics =
        str_contains(strtolower($activeUnitContext ?? ''), 'digital') ||
        str_contains(strtolower($activeUnitContext ?? ''), 'physical') ||
        str_contains(strtolower($reqFrom ?? ''), 'digital') ||
        str_contains(strtolower($reqFrom ?? ''), 'physical') ||
        request()->is('Digital_Forensics*') ||
        request()->is('digital-forensics*') ||
        (isset($authUser) &&
            (str_contains(strtolower($authUser->unit ?? ''), 'digital') ||
                str_contains(strtolower($authUser->unit ?? ''), 'physical')));
    $isEvidenceManagement =
        str_contains(strtolower($activeUnitContext ?? ''), 'evidence') ||
        str_contains(strtolower($reqFrom ?? ''), 'evidence') ||
        request()->is('Evidence_Management*') ||
        request()->is('evidence-management*') ||
        (isset($authUser) && str_contains(strtolower($authUser->unit ?? ''), 'evidence'));

    $isLabContext =
        request()->is('Lab_Analysis*') ||
        request()->is('lab-analysis*') ||
        request()->is('lab-result*') ||
        request()->query('unit') === 'Lab Analysis' ||
        request()->query('from') === 'lab' ||
        (str_contains(strtolower($activeUnitContext ?? ''), 'lab') &&
            !$isEvidenceManagement &&
            !$isDigitalForensics &&
            !request()->is('Crime_Scene_Support*') &&
            !request()->is('Evidence_Management*') &&
            !request()->is('Digital_Forensics*'));
    $isLabAnalysis = isset($isLabAnalysis)
        ? $isLabAnalysis
        : $isLabContext && !$isDigitalForensics && !$isEvidenceManagement;
    $isCrimeSceneContext =
        (str_contains(strtolower($activeUnitContext), 'crime') ||
            str_contains(strtolower($reqFrom ?? ''), 'crime') ||
            request()->is('Crime_Scene_Support*') ||
            request()->is('crime-scene-support*')) &&
        !$isHof &&
        !$isLabContext &&
        !$isDigitalForensics &&
        !$isEvidenceManagement;
    $isForensicHeadContext =
        $isHof ||
        request()->is('Forensic_Head*') ||
        session('user_role') === 'HOF' ||
        str_contains(strtolower($reqFrom ?? ''), 'forensic');

    $status = $case->status ?? 'Awaiting Sign-off';
    $priority = strtoupper($case->priority ?? 'HIGH');

    $docketData = is_array($case->docket_data)
        ? $case->docket_data
        : (json_decode($case->docket_data ?? '[]', true) ?:
        []);

    $checkIsDrugExhibit = function ($item) {
        if (empty($item)) {
            return false;
        }
        if (is_object($item)) {
            $item = (array) $item;
        }
        if (!is_array($item)) {
            return false;
        }
        $cat = strtolower(trim((string) ($item['exhibit_category'] ?? ($item['category'] ?? ''))));
        $type = strtolower(trim((string) ($item['exhibit_type'] ?? ($item['type'] ?? ''))));
        $dName = strtolower(trim((string) ($item['seizure_name_drug'] ?? '')));

        if (str_contains($cat, 'non-drug') || str_contains($type, 'non-drug')) {
            return false;
        }
        $nonDrugCategories = ['electronic', 'digital', 'device', 'phone', 'laptop', 'computer', 'weapon', 'vehicle', 'currency', 'cash', 'gold', 'precious', 'stone', 'diamond', 'sim card'];
        foreach ($nonDrugCategories as $ndc) {
            if (str_contains($cat, $ndc) && empty($dName)) {
                return false;
            }
        }
        if (!empty($dName) && !in_array($dName, ['n/a', 'none', 'null', '-', 'unknown'])) {
            return true;
        }
        return (str_contains($cat, 'drug') || str_contains($cat, 'narcotic') || (str_contains($type, 'drug') && !str_contains($type, 'non-drug')));
    };

    $exCat = strtolower($case->exhibit_category ?? '');
    $dSeizures = $docketData['seizures'] ?? [];
    $hasDrugSeizureInDocket = false;
    if (is_array($dSeizures)) {
        foreach ($dSeizures as $sz) {
            if ($checkIsDrugExhibit($sz)) {
                $hasDrugSeizureInDocket = true;
                break;
            }
        }
    }
    $isDrugCase =
        (!str_contains($exCat, 'non-drug') && (str_contains($exCat, 'drug') || str_contains($exCat, 'narcotic'))) ||
        $hasDrugSeizureInDocket;

    $primarySuspectName = strtolower(trim($case->suspect_name ?? ''));

    $allAssocPhotos = [];
    if (!empty($docketData['seizures']) && is_array($docketData['seizures'])) {
        foreach ($docketData['seizures'] as $szItem) {
            $assocPerson = strtolower(trim($szItem['associated_person'] ?? ($szItem['suspect_name'] ?? '')));
            $assocRole = strtolower(trim($szItem['association_role'] ?? ($szItem['role'] ?? '')));
            $isExplicitAssoc = !empty($szItem['is_associate']);

            $isPrimaryOwner =
                empty($assocPerson) ||
                (!empty($primarySuspectName) && $assocPerson === $primarySuspectName) ||
                $assocPerson === 'primary suspect' ||
                $assocPerson === 'primary' ||
                str_contains($assocPerson, 'all suspect') ||
                str_contains($assocPerson, 'joint');

            $isAssocRole = !empty($assocRole) && str_contains($assocRole, 'associate');
            $isAssocSz =
                ($isExplicitAssoc || $isAssocRole || (!$isPrimaryOwner && !empty($assocPerson))) && !$isPrimaryOwner;

            if ($isAssocSz) {
                $aPhotos = $szItem['evidence_photos'] ?? ($szItem['photos'] ?? []);
                if (is_array($aPhotos)) {
                    foreach ($aPhotos as $ap) {
                        if ($ap && !in_array($ap, $allAssocPhotos)) {
                            $allAssocPhotos[] = $ap;
                        }
                    }
                }
                $apSingle = $szItem['photo'] ?? ($szItem['exhibit_photo'] ?? null);
                if ($apSingle && !in_array($apSingle, $allAssocPhotos)) {
                    $allAssocPhotos[] = $apSingle;
                }
            }
        }
    }
    if (!empty($docketData['associated_seizures']) && is_array($docketData['associated_seizures'])) {
        foreach ($docketData['associated_seizures'] as $aEx) {
            $aPhotos = $aEx['evidence_photos'] ?? ($aEx['photos'] ?? []);
            if (is_array($aPhotos)) {
                foreach ($aPhotos as $ap) {
                    if ($ap && !in_array($ap, $allAssocPhotos)) {
                        $allAssocPhotos[] = $ap;
                    }
                }
            }
            $apSingle = $aEx['photo'] ?? ($aEx['exhibit_photo'] ?? null);
            if ($apSingle && !in_array($apSingle, $allAssocPhotos)) {
                $allAssocPhotos[] = $apSingle;
            }
        }
    }
    if (!empty($docketData['associate_exhibits']) && is_array($docketData['associate_exhibits'])) {
        foreach ($docketData['associate_exhibits'] as $aEx) {
            $aPhotos = $aEx['evidence_photos'] ?? ($aEx['photos'] ?? []);
            if (is_array($aPhotos)) {
                foreach ($aPhotos as $ap) {
                    if ($ap && !in_array($ap, $allAssocPhotos)) {
                        $allAssocPhotos[] = $ap;
                    }
                }
            }
            $apSingle = $aEx['photo'] ?? ($aEx['exhibit_photo'] ?? null);
            if ($apSingle && !in_array($apSingle, $allAssocPhotos)) {
                $allAssocPhotos[] = $apSingle;
            }
        }
    }

    $rawPhotos = is_array($case->evidence_photos)
        ? $case->evidence_photos
        : (json_decode($case->evidence_photos ?? '[]', true) ?:
        $docketData['evidence_photos'] ?? []);
    if (!is_array($rawPhotos)) {
        $rawPhotos = [];
    }

    $primaryPhotos = [];
    if (!empty($docketData['seizures']) && is_array($docketData['seizures'])) {
        foreach ($docketData['seizures'] as $szItem) {
            $assocPerson = strtolower(trim($szItem['associated_person'] ?? ($szItem['suspect_name'] ?? '')));
            $assocRole = strtolower(trim($szItem['association_role'] ?? ($szItem['role'] ?? '')));
            $isExplicitAssoc = !empty($szItem['is_associate']);

            $isPrimaryOwner =
                empty($assocPerson) ||
                (!empty($primarySuspectName) && $assocPerson === $primarySuspectName) ||
                $assocPerson === 'primary suspect' ||
                $assocPerson === 'primary' ||
                str_contains($assocPerson, 'all suspect') ||
                str_contains($assocPerson, 'joint');

            $isAssocRole = !empty($assocRole) && str_contains($assocRole, 'associate');
            $isAssocSz =
                ($isExplicitAssoc || $isAssocRole || (!$isPrimaryOwner && !empty($assocPerson))) && !$isPrimaryOwner;

            if (!$isAssocSz) {
                $pPhotos = $szItem['evidence_photos'] ?? ($szItem['photos'] ?? []);
                if (is_array($pPhotos)) {
                    foreach ($pPhotos as $p) {
                        if ($p && !in_array($p, $primaryPhotos) && !in_array($p, $allAssocPhotos)) {
                            $primaryPhotos[] = $p;
                        }
                    }
                }
                $singleP = $szItem['photo'] ?? ($szItem['exhibit_photo'] ?? null);
                if ($singleP && !in_array($singleP, $primaryPhotos) && !in_array($singleP, $allAssocPhotos)) {
                    $primaryPhotos[] = $singleP;
                }
            }
        }
    }

    foreach ($rawPhotos as $p) {
        if ($p && !in_array($p, $primaryPhotos) && !in_array($p, $allAssocPhotos)) {
            $primaryPhotos[] = $p;
        }
    }
    if (!empty($docketData['evidence_photos']) && is_array($docketData['evidence_photos'])) {
        foreach ($docketData['evidence_photos'] as $p) {
            if ($p && !in_array($p, $primaryPhotos) && !in_array($p, $allAssocPhotos)) {
                $primaryPhotos[] = $p;
            }
        }
    }

    $primaryPhotos = array_values(
        array_filter($primaryPhotos, function ($p) use ($allAssocPhotos) {
            return !in_array($p, $allAssocPhotos);
        }),
    );

    // Determine if the case involves drugs/narcotics
    $exhibitCategory = strtolower($case->exhibit_category ?? '');
    $seizureNameDrug = $case->seizure_name_drug ?? '';
    $seizureName = strtolower($case->seizure_name ?? '');
    $exhibitsSummary = strtolower($case->exhibits_summary ?? '');
    $offense = strtolower($case->offense ?? '');

    // Gather all exhibit items across case model and docket suspects/seizures
    $primaryExhibitsCheck = [];
    if (!empty($case->exhibit_category) || !empty($case->seizure_name_drug) || !empty($case->seizure_name)) {
        $primaryExhibitsCheck[] = [
            'category' => $case->exhibit_category ?? '',
            'seizure_name_drug' => $case->seizure_name_drug ?? '',
            'seizure_name' => $case->seizure_name ?? '',
        ];
    }
    if (!empty($docketData['seizures']) && is_array($docketData['seizures'])) {
        foreach ($docketData['seizures'] as $sz) {
            $isAssoc =
                !empty($sz['is_associate']) ||
                !empty($sz['associated_person']) ||
                (!empty($sz['association_role']) && str_contains(strtolower($sz['association_role']), 'associate'));
            if (!$isAssoc) {
                $primaryExhibitsCheck[] = $sz;
            }
        }
    }

    $isPrimaryDrugCase = false;
    $allExhibitsCheck = [];
    if (!empty($case->exhibit_category) || !empty($case->seizure_name_drug) || !empty($case->seizure_name)) {
        $allExhibitsCheck[] = [
            'category' => $case->exhibit_category ?? '',
            'exhibit_category' => $case->exhibit_category ?? '',
            'exhibit_type' => $case->exhibit_type ?? '',
            'seizure_name_drug' => $case->seizure_name_drug ?? '',
            'seizure_name' => $case->seizure_name ?? '',
        ];
    }
    if (!empty($docketData['seizures']) && is_array($docketData['seizures'])) {
        foreach ($docketData['seizures'] as $sz) {
            $allExhibitsCheck[] = $sz;
        }
    }
    if (!empty($docketData['associated_seizures']) && is_array($docketData['associated_seizures'])) {
        foreach ($docketData['associated_seizures'] as $aEx) {
            $allExhibitsCheck[] = $aEx;
        }
    }
    if (!empty($docketData['associate_exhibits']) && is_array($docketData['associate_exhibits'])) {
        foreach ($docketData['associate_exhibits'] as $aEx) {
            $allExhibitsCheck[] = $aEx;
        }
    }

    $isAnyDrugCase = false;
    foreach ($allExhibitsCheck as $exCheck) {
        if ($checkIsDrugExhibit($exCheck)) {
            $isAnyDrugCase = true;
            break;
        }
    }

    foreach ($primaryExhibitsCheck as $exCheck) {
        if ($checkIsDrugExhibit($exCheck)) {
            $isPrimaryDrugCase = true;
            break;
        }
    }

    // A case is strictly considered a drug case only when definitive drug exhibit or seizure data is present
    $hasDefinitiveDrugData = $isDrugCase || $isPrimaryDrugCase || $isAnyDrugCase ||
        (!empty($case->seizure_name_drug) && !in_array(strtolower(trim($case->seizure_name_drug)), ['n/a', 'none', 'null', '-'])) ||
        (!empty($hasDrugSeizureInDocket) && $hasDrugSeizureInDocket);

    // Prevent digital cases from being falsely flagged via generic case-level method fallback
    $isDrugCase = $hasDefinitiveDrugData || (!$isDigitalForensics && empty($allExhibitsCheck) && (method_exists($case, 'isDrugCase') ? $case->isDrugCase() : false));

    $controllerUser = $case->getControllerUser();
    $isCaseController =
        $authUser &&
        (!empty($authUser->is_head) ||
            $isHof ||
            strtolower($authUser->role ?? '') === 'admin' ||
            (isset($authUser->unit) && str_contains(strtolower($authUser->unit), 'head')));
    $activeHandover = $case->getActiveHandover();
    $currentCaseStatus = $case->case_status ?? 'Under Investigation';

    // Case Creator resolution: strictly resolved from the user who created/logged the case
    $caseCreatorName = $case->user?->fullname
        ?? ($case->user?->username ?? ($docketData['created_by_name'] ?? 'Investigating Officer'));
    $caseCreatorUnit = $case->user?->unit ?? ($case->unit_name ?? 'NACOC Forensic');
    $caseCreatedAt = $case->created_at ? $case->created_at->format('d M Y, H:i') : null;

    // Arresting Officer resolution
    $arrestingOfficerName = $case->arresting_officer ?? ($case->submitting_officer ?? 'N/A');

    // Case Status Updater resolution from AuditLog or docket_data
    $statusAudit = \App\Models\AuditLog::where('case_number', $case->case_number)
        ->whereIn('action', ['CASE_STATUS_CHANGED', 'CASE_STATUS_UPDATED'])
        ->latest('id')
        ->first();
    $statusUpdatedBy = $statusAudit->user_name ?? ($docketData['case_status_updated_by'] ?? null);
    $statusUpdatedByUnit = $statusAudit->user_unit ?? ($docketData['case_status_updated_by_unit'] ?? null);
    $statusUpdatedAt = $statusAudit ? $statusAudit->created_at->format('d M Y, H:i') : ($docketData['case_status_updated_at'] ?? null);

    // GATHER ALL SUSPECTS IN THIS CASE TO RESOLVE THE SELECTED SUSPECT
    $allSuspectsInCase = [];
    if (!empty($docketData['suspects']) && is_array($docketData['suspects'])) {
        foreach ($docketData['suspects'] as $sIndex => $sp) {
            if (!empty($sp['suspect_name'])) {
                $spRole = $sp['association_role'] ?? ($sp['role'] ?? ($sIndex === 0 ? 'Primary Suspect' : 'Associate'));
                $isPrimary = $sIndex === 0 || strtolower($spRole) === 'primary suspect';
                $allSuspectsInCase[] = [
                    'id' => $sp['id'] ?? null,
                    'associate_id' => $sp['associate_id'] ?? ($sp['suspect_id'] ?? null),
                    'name' => trim($sp['suspect_name']),
                    'alias' => $sp['suspect_alias'] ?? 'N/A',
                    'role' => $spRole,
                    'is_primary' => $isPrimary,
                    'is_associate' => !$isPrimary,
                ];
            }
        }
    }
    if (empty($allSuspectsInCase)) {
        $allSuspectsInCase[] = [
            'name' => trim($case->suspect_name ?? 'Primary Suspect'),
            'alias' => $case->suspect_alias ?? 'N/A',
            'role' => 'Primary Suspect',
            'is_primary' => true,
            'is_associate' => false,
        ];
    }

    // RESOLVE ACTIVE SUSPECT FROM QUERY PARAMETER OR DEFAULT TO FIRST SUSPECT
    $reqSuspectParam = request()->query('suspect');
    $activeSuspectItem = $allSuspectsInCase[0];
    if (!empty($reqSuspectParam)) {
        foreach ($allSuspectsInCase as $sCandidate) {
            if (strtolower(trim($sCandidate['name'])) === strtolower(trim($reqSuspectParam))) {
                $activeSuspectItem = $sCandidate;
                break;
            }
        }
    }
    $activeSuspectName = $activeSuspectItem['name'];
    $activeSuspectNameLower = strtolower(trim($activeSuspectName));
    $isActiveSuspectPrimary = !empty($activeSuspectItem['is_primary']);

    // STRICT SUSPECT-LEVEL EXHIBIT LINKING
    $suspectLinkedExhibits = [];
    $allSeizuresList = array_merge(
        $docketData['seizures'] ?? [],
        $docketData['associated_seizures'] ?? [],
        $docketData['associate_exhibits'] ?? [],
    );

    foreach ($allSeizuresList as $sz) {
        $assocPerson = strtolower(trim($sz['associated_person'] ?? ($sz['suspect_name'] ?? ($sz['owner_name'] ?? ''))));
        $isLinked = false;
        if (!empty($assocPerson)) {
            if (
                $assocPerson === $activeSuspectNameLower ||
                str_contains($assocPerson, $activeSuspectNameLower) ||
                str_contains($activeSuspectNameLower, $assocPerson)
            ) {
                $isLinked = true;
            } elseif (
                str_contains($assocPerson, 'all suspect') ||
                str_contains($assocPerson, 'joint') ||
                ($isActiveSuspectPrimary && ($assocPerson === 'primary suspect' || $assocPerson === 'primary'))
            ) {
                $isLinked = true;
            }
        } elseif ($isActiveSuspectPrimary) {
            $isLinked = true;
        }

        if ($isLinked) {
            $suspectLinkedExhibits[] = $sz;
        }
    }

    // Include top-level case exhibit if active suspect is primary
    if (
        $isActiveSuspectPrimary &&
        (!empty($case->exhibit_category) || !empty($case->seizure_name_drug) || !empty($case->seizure_name))
    ) {
        $suspectLinkedExhibits[] = [
            'category' => $case->exhibit_category ?? '',
            'seizure_name_drug' => $case->seizure_name_drug ?? '',
            'seizure_name' => $case->seizure_name ?? '',
        ];
    }

    // CLASSIFY EXHIBIT CATEGORIES FOR ACTIVE SUSPECT
    $suspectHasDrug = false;
    $suspectHasElectronic = false;
    $suspectHasCrimeScene = false;

    foreach ($suspectLinkedExhibits as $ex) {
        $cat = strtolower($ex['category'] ?? ($ex['exhibit_category'] ?? ''));
        $type = strtolower($ex['exhibit_type'] ?? '');
        $dName = strtolower($ex['seizure_name_drug'] ?? '');
        $sName = strtolower(
            $ex['seizure_name'] ?? ($ex['name'] ?? ($ex['commodity_name'] ?? ($ex['description'] ?? ''))),
        );

        if ($checkIsDrugExhibit($ex)) {
            $suspectHasDrug = true;
        }

        if (str_contains($cat, 'electronic') || str_contains($cat, 'digital') || str_contains($cat, 'device')
            || str_contains($type, 'electronic') || str_contains($type, 'phone') || str_contains($type, 'laptop')
            || str_contains($sName, 'phone') || str_contains($sName, 'laptop') || str_contains($sName, 'sim')
            || str_contains($sName, 'hard drive') || str_contains($sName, 'flash drive') || str_contains($sName, 'tablet')
        ) {
            $suspectHasElectronic = true;
        }

        if (str_contains($cat, 'weapon') || str_contains($cat, 'ammunition') || str_contains($cat, 'vehicle')
            || str_contains($cat, 'currency') || str_contains($cat, 'cash') || str_contains($cat, 'money') || str_contains($cat, 'gold') || str_contains($cat, 'precious') || str_contains($cat, 'stone')
            || str_contains($sName, 'weapon') || str_contains($sName, 'vehicle') || str_contains($sName, 'car') || str_contains($sName, 'cash')
        ) {
            $suspectHasCrimeScene = true;
        }
    }

    $activeSuspectHasDrugExhibit = (bool) !empty($suspectHasDrug);
    $hasAnySpecialistUnit = $suspectHasCrimeScene || $suspectHasDrug || $suspectHasElectronic;

    // CHECK IF VALID EXAMINATION INFORMATION HAS ACTUALLY BEEN SAVED FOR THIS SELECTED SUSPECT
    $suspectLabExamSaved = false;

    if ($activeSuspectHasDrugExhibit) {
        // 1. Check AssociateLabExamination model strictly matching active suspect name
        if (!empty($case->id)) {
            $suspectLabExamSaved = \App\Models\AssociateLabExamination::where('case_id', $case->id)
                ->where('has_saved', true)
                ->get()
                ->contains(function ($aRec) use ($activeSuspectNameLower) {
                    if (empty($aRec->has_saved)) return false;
                    if (empty($aRec->analyst) && empty($aRec->exam_reference) && empty($aRec->substance_identification) && empty($aRec->date_completed)) return false;
                    $aName = strtolower(trim($aRec->suspect_name ?? ''));
                    return !empty($aName) &&
                        ($aName === $activeSuspectNameLower ||
                            str_contains($aName, $activeSuspectNameLower) ||
                            str_contains($activeSuspectNameLower, $aName));
                });
        }

        // 2. If primary suspect, check LaboratoryExaminationResult model
        if (!$suspectLabExamSaved && $isActiveSuspectPrimary && !empty($case->id)) {
            $suspectLabExamSaved = \App\Models\LaboratoryExaminationResult::where(function ($q) use ($case, $isMultiCase) {
                if ($isMultiCase) {
                    $q->where('multiple_suspect_case_id', $case->id);
                } else {
                    $q->where('single_suspect_case_id', $case->id);
                }
            })
                ->where('has_saved', true)
                ->where(function ($q) {
                    $q->where(function ($sub) {
                        $sub->whereNotNull('analyst')->where('analyst', '!=', '');
                    })->orWhere(function ($sub) {
                        $sub->whereNotNull('exam_reference')->where('exam_reference', '!=', '');
                    })->orWhere(function ($sub) {
                        $sub->whereNotNull('substance_identification')->where('substance_identification', '!=', '');
                    })->orWhere(function ($sub) {
                        $sub->whereNotNull('date_completed')->where('date_completed', '!=', '');
                    });
                })
                ->exists();
        }

        // 3. Check lab_examinations_list strictly matching active suspect name
        if (
            !$suspectLabExamSaved &&
            !empty($docketData['lab_examinations_list']) &&
            is_array($docketData['lab_examinations_list'])
        ) {
            foreach ($docketData['lab_examinations_list'] as $lItem) {
                $lOwner = strtolower(trim($lItem['exhibit_owner_name'] ?? ''));
                if (
                    !empty($lItem['has_saved']) &&
                    ($lOwner === $activeSuspectNameLower ||
                        str_contains($lOwner, $activeSuspectNameLower) ||
                        str_contains($activeSuspectNameLower, $lOwner))
                ) {
                    $suspectLabExamSaved = true;
                    break;
                }
            }
        }

        // 4. Check associate_lab_examinations in docket_data
        if (
            !$suspectLabExamSaved &&
            !empty($docketData['associate_lab_examinations']) &&
            is_array($docketData['associate_lab_examinations'])
        ) {
            foreach ($docketData['associate_lab_examinations'] as $kAssoc => $vAssoc) {
                $kLow = strtolower(trim($kAssoc));
                if (
                    !empty($vAssoc['has_saved']) &&
                    ($kLow === $activeSuspectNameLower ||
                        str_contains($kLow, $activeSuspectNameLower) ||
                        str_contains($activeSuspectNameLower, $kLow))
                ) {
                    $suspectLabExamSaved = true;
                    break;
                }
            }
        }

        // 5. Check primary lab_examination in docket_data
        if (!$suspectLabExamSaved && $isActiveSuspectPrimary && !empty($docketData['lab_examination'])) {
            $hasLabData = !empty($docketData['lab_examination']['has_saved']);
            if ($hasLabData) {
                $pOwner = strtolower(trim($docketData['lab_examination']['exhibit_owner_name'] ?? ''));
                if (
                    empty($pOwner) ||
                    $pOwner === 'primary suspect' ||
                    $pOwner === $activeSuspectNameLower ||
                    str_contains($pOwner, $activeSuspectNameLower) ||
                    str_contains($activeSuspectNameLower, $pOwner)
                ) {
                    $suspectLabExamSaved = true;
                }
            }
        }

        // 6. Check seizures linked to this suspect in docket_data
        if (!$suspectLabExamSaved) {
            foreach ($suspectLinkedExhibits as $szItem) {
                if (!empty($szItem['has_saved_lab'])) {
                    $suspectLabExamSaved = true;
                    break;
                }
            }
        }
    }

    // STRICT: only accept records where Lab Analysis has explicitly marked has_saved.
    // Do NOT trust case-model columns (confirmatory_test_result, presumptive_test_result,
    // substance_identification) — those are exhibit-registration metadata, not lab output.
    $caseHasAnySavedLab = (bool) (
        $suspectLabExamSaved
        || !empty($docketData['lab_examination']['has_saved'])
        || (!empty($docketData['lab_examinations_list'])
            && is_array($docketData['lab_examinations_list'])
            && collect($docketData['lab_examinations_list'])->contains(fn ($l) => !empty($l['has_saved'])))
        || (!empty($docketData['associate_lab_examinations'])
            && is_array($docketData['associate_lab_examinations'])
            && collect($docketData['associate_lab_examinations'])->contains(fn ($a) => !empty($a['has_saved'])))
        || (!empty($docketData['seizures'])
            && is_array($docketData['seizures'])
            && collect($docketData['seizures'])->contains(fn ($s) => !empty($s['has_saved_lab'])))
    );

    // -------------------------------------------------------------------------
    // DYNAMIC UNITS LIST DETERMINATION FOR SELECTED SUSPECT
    // (Operational Units only; HOF is the dedicated Final Step card)
    // -------------------------------------------------------------------------
    // WHY: The NACOC Inter-Unit Workflow tracker should only display unit cards for
    // directorates genuinely involved in the case, preventing clutter from idle or
    // unreferenced units.
    //
    // THE TWO-CONDITION RULE:
    // 1. Case Creator: The unit that originally logged the case must always appear (first).
    // 2. Contributing Units: Any unit that subsequently made any add-on to the case
    //    (added exhibits, submitted findings/examinations, or progressed the workflow)
    //    must appear.
    //
    // ONE ALWAYS-VISIBLE DEFAULT CARD:
    // 1. Evidence Management: Required for all cases as the final operational stage.
    //    Always appended at the end of $unitsList.
    //
    // DEFINITION OF INVOLVEMENT:
    // A unit is considered involved if any of the following 6 criteria are met:
    // (1) Case creator: $case->unit_name matches that unit.
    // (2) Non-pending status: docket_data['unit_progress'][unit]['status'] is not PENDING.
    // (3) Recorded officer: docket_data['unit_progress'][unit]['officer'] is present.
    // (4) Lab examination record: Saved lab examination result or docket lab entry exists.
    // (5) Digital forensics record: Digital extraction/report or court order exists.
    // (6) Exhibit association: An exhibit is linked to that unit's domain
    //     (e.g., electronic exhibit -> Digital Forensics, drug exhibit -> Lab Analysis,
    //      weapons/vehicles/currency/gold -> Crime Scene Support).
    // -------------------------------------------------------------------------

    // Read canonical unit names from enum (avoiding hardcoded strings)
    $cssUnit = enum_exists(\App\Enums\UnitName::class)
        ? \App\Enums\UnitName::CRIME_SCENE_SUPPORT->value
        : 'Crime Scene Support';
    $labUnit = enum_exists(\App\Enums\UnitName::class)
        ? \App\Enums\UnitName::LAB_ANALYSIS->value
        : 'Lab Analysis';
    $dpfUnit = enum_exists(\App\Enums\UnitName::class)
        ? \App\Enums\UnitName::DIGITAL_PHYSICAL_FORENSICS->value
        : 'Digital & Physical Forensics';
    $emUnit = enum_exists(\App\Enums\UnitName::class)
        ? \App\Enums\UnitName::EVIDENCE_MANAGEMENT->value
        : 'Evidence Management';

    // 1. Determine case creator unit
    $caseUnitRaw = trim($case->unit_name ?? ($case->unit?->name ?? ($case->user?->unit ?? ($docketData['created_by_unit'] ?? ''))));
    $caseUnitLower = strtolower($caseUnitRaw);
    $caseNumberUpper = strtoupper($case->case_number ?? '');

    $isCreatorEvidence = ($caseUnitLower === strtolower($emUnit))
        || str_contains($caseUnitLower, 'evidence')
        || str_starts_with($caseNumberUpper, 'EM-')
        || str_starts_with($caseNumberUpper, 'EVD-');

    $isCreatorLab = ($caseUnitLower === strtolower($labUnit))
        || str_contains($caseUnitLower, 'lab')
        || str_starts_with($caseNumberUpper, 'LAB-')
        || str_starts_with($caseNumberUpper, 'FSL-');

    $isCreatorDpf = ($caseUnitLower === strtolower($dpfUnit))
        || str_contains($caseUnitLower, 'digital')
        || str_contains($caseUnitLower, 'physical')
        || str_starts_with($caseNumberUpper, 'DPF-')
        || str_starts_with($caseNumberUpper, 'DIG-');

    $isCreatorCss = !$isCreatorEvidence && !$isCreatorLab && !$isCreatorDpf && (
        ($caseUnitLower === strtolower($cssUnit))
        || str_contains($caseUnitLower, 'crime')
        || str_contains($caseUnitLower, 'scene')
        || str_starts_with($caseNumberUpper, 'CSS-')
        || empty($caseUnitLower)
    );

    // 2 & 3. Closures to inspect docket_data['unit_progress'] for active progress or recorded officer
    $unitHasActiveProgress = function (string $unitKey) use ($docketData): bool {
        if (empty($docketData['unit_progress'][$unitKey]['status'])) {
            return false;
        }
        $st = strtoupper(trim((string) $docketData['unit_progress'][$unitKey]['status']));
        return $st !== '' && $st !== 'PENDING';
    };

    $unitHasRecordedOfficer = function (string $unitKey) use ($docketData): bool {
        return !empty($docketData['unit_progress'][$unitKey]['officer'])
            && trim((string) $docketData['unit_progress'][$unitKey]['officer']) !== '';
    };

    // STRICT: only accept entries where has_saved is explicitly true.
    $hasLabRecord = (bool) (
        $suspectLabExamSaved
        || !empty($docketData['lab_examination']['has_saved'])
        || (!empty($docketData['lab_examinations_list'])
            && is_array($docketData['lab_examinations_list'])
            && collect($docketData['lab_examinations_list'])->contains(fn ($l) => !empty($l['has_saved'])))
        || (!empty($docketData['associate_lab_examinations'])
            && is_array($docketData['associate_lab_examinations'])
            && collect($docketData['associate_lab_examinations'])->contains(fn ($a) => !empty($a['has_saved'])))
    );

    // 5. Digital Forensics Record exists for active suspect (Condition 5)
    $suspectHasDigitalRecord = false;
    $suspectDigitalSavedRecord = null;
    if (!empty($docketData['digital_forensics']) && is_array($docketData['digital_forensics'])) {
        if (isset($docketData['digital_forensics'][$activeSuspectNameLower]) && is_array($docketData['digital_forensics'][$activeSuspectNameLower])) {
            $candidate = $docketData['digital_forensics'][$activeSuspectNameLower];
            if (!empty($candidate['has_saved']) || !empty($candidate['analyst']) || !empty($candidate['report']) || !empty($candidate['extraction_data']) || !empty($candidate['forensic_status'])) {
                $suspectHasDigitalRecord = true;
                if (!empty($candidate['has_saved'])) {
                    $suspectDigitalSavedRecord = $candidate;
                }
            }
        }
        if (!$suspectHasDigitalRecord) {
            foreach ($docketData['digital_forensics'] as $dfK => $dfEntry) {
                if (is_array($dfEntry)) {
                    $dfSuspect = strtolower(trim((string)($dfEntry['suspect_name'] ?? ($dfEntry['owner_name'] ?? $dfK))));
                    $isMatch = ($dfSuspect === $activeSuspectNameLower)
                        || str_contains($dfSuspect, $activeSuspectNameLower)
                        || str_contains($activeSuspectNameLower, $dfSuspect)
                        || ($isActiveSuspectPrimary && in_array($dfSuspect, ['primary', 'primary suspect', '']));
                    if ($isMatch && (!empty($dfEntry['has_saved']) || !empty($dfEntry['analyst']) || !empty($dfEntry['report']) || !empty($dfEntry['extraction_data']) || !empty($dfEntry['forensic_status']))) {
                        $suspectHasDigitalRecord = true;
                        if (!empty($dfEntry['has_saved'])) {
                            $suspectDigitalSavedRecord = $dfEntry;
                        }
                        break;
                    }
                }
            }
        }
    }
    if (!$suspectHasDigitalRecord && $isActiveSuspectPrimary && (!empty($docketData['digital_court_orders']) || !empty($docketData['digital_reports']))) {
        $suspectHasDigitalRecord = true;
    }

    // 6. Exhibit associated with unit's domain — strictly scoped to active suspect (Condition 6)
    $suspectHasDrugExhibit = (bool) ($suspectHasDrug || $activeSuspectHasDrugExhibit);
    $suspectHasElectronicExhibit = (bool) $suspectHasElectronic;
    $suspectHasCrimeSceneExhibit = (bool) $suspectHasCrimeScene;

    // Evaluate involvement per unit — strictly suspect-scoped (Conditions 1 to 6)
    $cssInvolved = $isCreatorCss
        || $unitHasActiveProgress($cssUnit)
        || $unitHasRecordedOfficer($cssUnit)
        || (!$isCreatorEvidence && $suspectHasCrimeSceneExhibit);

    $labInvolved = $isCreatorLab
        || $unitHasActiveProgress($labUnit)
        || $unitHasRecordedOfficer($labUnit)
        || $suspectLabExamSaved
        || ($isActiveSuspectPrimary && $hasLabRecord)
        || $suspectHasDrugExhibit;

    $dpfInvolved = $isCreatorDpf
        || $unitHasActiveProgress($dpfUnit)
        || $unitHasRecordedOfficer($dpfUnit)
        || $suspectHasDigitalRecord
        || $suspectHasElectronicExhibit;

    // =========================================================================
    // THE TWO-CONDITION RULE FOR $unitsList ASSEMBLY
    // Step 1 — Creator unit first.
    // Step 2 — Other contributing units next, in canonical order (CSS, Lab Analysis, DPF),
    //          skipping the creator unit and any unit where *Involved is false.
    // Step 3 — Evidence Management is always appended last.
    // Step 4 — Head of Forensic Directorate is never in $unitsList.
    // =========================================================================

    // Step 1: Creator unit first
    $creatorUnit = null;
    if ($isCreatorLab) {
        $creatorUnit = $labUnit;
        $labInvolved = true;
    } elseif ($isCreatorDpf) {
        $creatorUnit = $dpfUnit;
        $dpfInvolved = true;
    } elseif ($isCreatorEvidence) {
        $creatorUnit = $emUnit;
    } else {
        $creatorUnit = $cssUnit;
        $isCreatorCss = true;
        $cssInvolved = true;
    }

    $unitsList = [];
    if (!empty($creatorUnit)) {
        $unitsList[] = $creatorUnit;
    }

    // Step 2: Contributing units in canonical order (CSS, Lab Analysis, DPF)
    $canonicalOperationalUnits = [$cssUnit, $labUnit, $dpfUnit];
    $involvedMap = [
        $cssUnit => $cssInvolved,
        $labUnit => $labInvolved,
        $dpfUnit => $dpfInvolved,
    ];

    foreach ($canonicalOperationalUnits as $opUnit) {
        if (!empty($involvedMap[$opUnit]) && !in_array($opUnit, $unitsList, true)) {
            $unitsList[] = $opUnit;
        }
    }

    // Step 3: Evidence Management appended if not creator
    if (!$isCreatorEvidence && !in_array($emUnit, $unitsList, true)) {
        $unitsList[] = $emUnit;
    }

    $unitsList = array_values(array_unique($unitsList));
    $totalUnitsCount = count($unitsList);

    // BUILD UNIT PROGRESS STATUSES STRICTLY FOR SELECTED SUSPECT
    $unitProgress = [];
    foreach ($unitsList as $uKey) {
        if ($uKey === 'Lab Analysis') {
            // Lab Analysis is COMPLETED iff a real saved examination exists for the active suspect
            $isLabDone = (bool) $suspectLabExamSaved;

            $labOfficerResolved = null;
            if (!empty($docketData['lab_examination']['analyst'])) {
                $labOfficerResolved = $docketData['lab_examination']['analyst'];
            } elseif (!empty($docketData['unit_progress']['Lab Analysis']['officer'])) {
                $labOfficerResolved = $docketData['unit_progress']['Lab Analysis']['officer'];
            } elseif (!empty($labAnalyst)) {
                $labOfficerResolved = $labAnalyst;
            } else {
                $labOfficerResolved = $case->submitting_officer ?? ($defaultLabHeadName ?? 'N/A');
            }

            $unitProgress[$uKey] = [
                'status' => $isLabDone ? 'COMPLETED' : 'PENDING',
                'officer' => $labOfficerResolved,
                'updated_at' => $isLabDone ? (optional($case->updated_at)->toDateTimeString() ?? date('Y-m-d H:i:s')) : null,
                'notes' => $isLabDone
                    ? 'Laboratory Examination Information completed and signed off'
                    : ($suspectHasDrugExhibit
                        ? 'Drug exhibit registered; awaiting Laboratory Examination Information entry'
                        : 'Awaiting lab testing'),
            ];
        } elseif ($uKey === 'Digital & Physical Forensics') {
            // Digital & Physical Forensics is COMPLETED iff a real saved digital forensics record exists
            // for the active suspect (or case created by DPF and output saved, or workflow status COMPLETED)
            $dpfWorkflowCompleted = !empty($docketData['unit_progress']['Digital & Physical Forensics']['status'])
                && strtoupper($docketData['unit_progress']['Digital & Physical Forensics']['status']) === 'COMPLETED';

            $dpfCreatorOutputSaved = $isCreatorDpf && (
                !empty($suspectDigitalSavedRecord)
                || !empty($docketData['digital_reports'])
                || !empty($docketData['digital_court_orders'])
                || $dpfWorkflowCompleted
            );

            $isDigDone = (!empty($suspectDigitalSavedRecord) && !empty($suspectDigitalSavedRecord['has_saved']))
                || $dpfCreatorOutputSaved
                || $dpfWorkflowCompleted;

            $digitalOfficerResolved = $suspectDigitalSavedRecord['analyst'] ?? (
                $docketData['digital_forensics'][$activeSuspectNameLower]['analyst'] ??
                ($docketData['unit_progress']['Digital & Physical Forensics']['officer'] ??
                    ($isCreatorDpf ? $case->submitting_officer ?? 'N/A' : 'N/A'))
            );

            $unitProgress[$uKey] = [
                'status' => $isDigDone ? 'COMPLETED' : 'PENDING',
                'officer' => $digitalOfficerResolved,
                'updated_at' => $isDigDone
                    ? (optional($case->updated_at)->toDateTimeString() ?? date('Y-m-d H:i:s'))
                    : null,
                'notes' => $isDigDone
                    ? 'Device extraction & digital forensic examination completed'
                    : ($suspectHasElectronicExhibit
                        ? 'Electronic device registered; awaiting digital forensic extraction'
                        : 'Awaiting device extraction'),
            ];
        } elseif ($uKey === 'Crime Scene Support') {
            // Crime Scene Support is COMPLETED iff a persisted CSS record exists for this case
            // (or unit_progress['Crime Scene Support']['status'] === 'COMPLETED').
            $cssProgressStatus = strtoupper(trim((string) ($docketData['unit_progress']['Crime Scene Support']['status'] ?? '')));
            $cssCompleted = ($cssProgressStatus === 'COMPLETED')
                || ($isCreatorCss && empty($cssProgressStatus) && !empty($case->id));

            $unitProgress[$uKey] = [
                'status' => $cssCompleted ? 'COMPLETED' : 'PENDING',
                'officer' => $docketData['unit_progress']['Crime Scene Support']['officer'] ?? ($case->user?->fullname ?? ($case->submitting_officer ?? null)),
                'updated_at' => $cssCompleted ? (optional($case->created_at)->toDateTimeString() ?? date('Y-m-d H:i:s')) : null,
                'notes' => $cssCompleted
                    ? 'Submitted via Crime Scene Support & Field Operations Workspace'
                    : 'Awaiting crime scene and field operations submission',
            ];
        } elseif ($uKey === 'Evidence Management') {
            // Evidence Management is COMPLETED iff unit_progress['Evidence Management']['status'] === 'COMPLETED'
            // or if Evidence Department is the creator unit that logged the case and evidence.
            $evProgressStatus = strtoupper(trim((string) ($docketData['unit_progress']['Evidence Management']['status'] ?? '')));
            $evCompleted = ($evProgressStatus === 'COMPLETED')
                || ($isCreatorEvidence && !empty($case->id));

            $unitProgress[$uKey] = [
                'status' => $evCompleted ? 'COMPLETED' : 'PENDING',
                'officer' => $docketData['unit_progress']['Evidence Management']['officer']
                    ?? ($case->user?->fullname ?? ($case->submitting_officer ?? 'Evidence Custodian')),
                'updated_at' => $evCompleted
                    ? ($docketData['unit_progress']['Evidence Management']['updated_at'] ?? (optional($case->created_at)->toDateTimeString() ?? date('Y-m-d H:i:s')))
                    : null,
                'notes' => $evCompleted
                    ? 'Processed via Evidence Management & Custody Vault Workspace'
                    : 'Awaiting evidence receipt and vault custody intake',
            ];
        }
    }

    $completedUnitsCount = 0;
    foreach ($unitsList as $uKey) {
        if (isset($unitProgress[$uKey]['status']) && strtoupper($unitProgress[$uKey]['status']) === 'COMPLETED') {
            $completedUnitsCount++;
        }
    }

    $primarySuspectNamesList = [];
    $coSuspectNamesList = [];
    $associateSuspectNamesList = [];
    if (!empty($docketData['suspects']) && is_array($docketData['suspects'])) {
        foreach ($docketData['suspects'] as $sp) {
            $role = strtolower($sp['association_role'] ?? ($sp['role'] ?? ''));
            $spIsAssoc = !empty($sp['is_associate']) || (!empty($role) && $role !== 'primary suspect');
            $spIsCo =
                $spIsAssoc &&
                ((!empty($sp['association_role']) &&
                    (str_contains(strtolower($sp['association_role']), 'co-suspect') ||
                        str_contains(strtolower($sp['association_role']), 'co suspect'))) ||
                    (!empty($sp['role']) &&
                        (str_contains(strtolower($sp['role']), 'co-suspect') ||
                            str_contains(strtolower($sp['role']), 'co suspect'))) ||
                    (!empty($sp['suspect_role']) &&
                        (str_contains(strtolower($sp['suspect_role']), 'co-suspect') ||
                            str_contains(strtolower($sp['suspect_role']), 'co suspect'))));
            if (!$spIsAssoc && !empty($sp['suspect_name'])) {
                $primarySuspectNamesList[] = $sp['suspect_name'];
            } elseif ($spIsCo && !empty($sp['suspect_name'])) {
                $coSuspectNamesList[] = $sp['suspect_name'];
            } elseif ($spIsAssoc && !empty($sp['suspect_name'])) {
                $associateSuspectNamesList[] = $sp['suspect_name'];
            }
        }
    }
    $primaryAndCoNamesList = array_unique(array_merge($primarySuspectNamesList, $coSuspectNamesList));

    $labExam = $docketData['lab_examination'] ?? [];
    if (empty($labExam['has_saved'])) {
        if (!empty($docketData['lab_examinations_list']) && is_array($docketData['lab_examinations_list'])) {
            foreach ($docketData['lab_examinations_list'] as $lItem) {
                if (!empty($lItem['has_saved'])) {
                    $labExam = array_merge($labExam, $lItem);
                    break;
                }
            }
        }
    }
    if (empty($labExam['has_saved'])) {
        if (!empty($docketData['seizures']) && is_array($docketData['seizures'])) {
            foreach ($docketData['seizures'] as $szItem) {
                if (!empty($szItem['has_saved_lab'])) {
                    $labExam = array_merge($labExam, [
                        'exhibit_owner_name' =>
                            $szItem['associated_person'] ??
                            ($szItem['suspect_name'] ?? ($szItem['owner_name'] ?? null)),
                        'laboratory_number' => $szItem['laboratory_number'] ?? null,
                        'exam_reference' => $szItem['exam_reference'] ?? null,
                        'exhibit_number' => $szItem['exhibit_number'] ?? null,
                        'analyst' => $szItem['analyst'] ?? null,
                        'date_received' => $szItem['date_received'] ?? null,
                        'date_started' => $szItem['date_started'] ?? null,
                        'date_completed' => $szItem['date_completed'] ?? null,
