                        );
                        if (!empty($pParts)) {
                            $primaryAndCoNamesArray[] = $pParts[0];
                        }
                    }

                    $namesMatchFuzzy = function ($name1, $name2) {
                        if (empty($name1) || empty($name2)) {
                            return false;
                        }
                        $n1 = strtolower(trim($name1));
                        $n2 = strtolower(trim($name2));
                        if ($n1 === $n2) {
                            return true;
                        }
                        if (str_contains($n1, $n2) || str_contains($n2, $n1)) {
                            return true;
                        }

                        $w1 = array_values(
                            array_filter(
                                explode(' ', preg_replace('/[^a-z0-9]/', ' ', $n1)),
                                fn($w) => strlen($w) >= 2,
                            ),
                        );
                        $w2 = array_values(
                            array_filter(
                                explode(' ', preg_replace('/[^a-z0-9]/', ' ', $n2)),
                                fn($w) => strlen($w) >= 2,
                            ),
                        );

                        if (empty($w1) || empty($w2)) {
                            return false;
                        }

                        if (count($w1) >= 2 && count($w2) >= 2) {
                            $last1 = end($w1);
                            $last2 = end($w2);
                            if ($last1 === $last2) {
                                $first1 = $w1[0];
                                $first2 = $w2[0];
                                if (
                                    $first1 === $first2 ||
                                    str_starts_with($first1, substr($first2, 0, 3)) ||
                                    str_starts_with($first2, substr($first1, 0, 3))
                                ) {
                                    return true;
                                }
                            }
                        }
                        return false;
                    };

                    $isDuplicatePrimaryCoEntry = function ($nameToCheck) use (
                        $primaryAndCoNamesArray,
                        $namesMatchFuzzy,
                    ) {
                        if (empty($nameToCheck) || empty($primaryAndCoNamesArray)) {
                            return false;
                        }
                        $clean = strtolower(trim($nameToCheck));

                        $parts = array_filter(array_map('trim', preg_split('/[,&]|\band\b/i', $clean)));
                        if (empty($parts)) {
                            return false;
                        }

                        if (count($parts) > 1) {
                            $allMatch = true;
                            foreach ($parts as $p) {
                                $found = false;
                                foreach ($primaryAndCoNamesArray as $pName) {
                                    if ($namesMatchFuzzy($p, $pName)) {
                                        $found = true;
                                        break;
                                    }
                                }
                                if (!$found) {
                                    $allMatch = false;
                                    break;
                                }
                            }
                            if ($allMatch) {
                                return true;
                            }
                        }

                        foreach ($primaryAndCoNamesArray as $pName) {
                            if ($namesMatchFuzzy($clean, $pName)) {
                                return true;
                            }
                        }

                        return false;
