                        $sSpouseP = $sItem['spouse_phone'] ?? ($sDocketSuspect['spouse_phone'] ?? ($sNum == 1 ? $case->spouse_phone : null));
                        $sSpouseI = $sItem['spouse_info'] ?? ($sDocketSuspect['spouse_info'] ?? ($sNum == 1 ? $case->spouse_info : null));
