                        $pickArrestValue = static function (array $candidates): ?string {
                            foreach ($candidates as $candidate) {
                                $val = trim((string) ($candidate ?? ''));
                                if ($val !== '' && !in_array(strtoupper($val), ['N/A', 'NA', '-', 'NULL', 'UNSPECIFIED'], true)) {
                                    return $val;
                                }
