                                foreach ($activeSuspectDrugExhibits as $sIdx => $sz) {
                                    if (!$checkIsDrugExhibitReview($sz)) {
                                        continue;
                                    }

                                    $cat = strtolower($sz['category'] ?? ($sz['exhibit_category'] ?? ''));
                                    $sName =
