                console.log('[NACOC DEBUG] Read-only display gates:', {
                    hasAnySavedLab: ro.dataset.hasAnySavedLab,
                    activeHasDrug: ro.dataset.activeHasDrug,
                    activeHasSavedResult: ro.dataset.activeHasSavedResult,
                });
            }
        });
    </script>

